"""Budget plan model — generated by FR-004 agent."""

import uuid

from sqlalchemy import ForeignKey, Integer
from sqlalchemy.dialects.postgresql import UUID, JSONB
from sqlalchemy.orm import Mapped, mapped_column

from app.db.base import Base, TimestampMixin, UUIDPrimaryKeyMixin


class BudgetPlan(Base, UUIDPrimaryKeyMixin, TimestampMixin):
    """AI-generated event budget."""

    __tablename__ = "budget_plans"

    event_id: Mapped[uuid.UUID] = mapped_column(
        UUID(as_uuid=True), ForeignKey("event_records.id", ondelete="CASCADE"),
        nullable=False, index=True, unique=True,
    )
    version: Mapped[int] = mapped_column(Integer, default=1, nullable=False)
    categories: Mapped[list] = mapped_column(JSONB, nullable=False)
    # categories = [
    #   {"name": "Venue", "items": [{"description": "...", "quantity": 1, "unit_cost": 50000, "total": 50000}], "subtotal": 50000},
    #   ...
    # ]
    contingency_percent: Mapped[int] = mapped_column(Integer, default=10, nullable=False)
    total_amount: Mapped[dict | None] = mapped_column(JSONB, nullable=True)
    warnings: Mapped[list | None] = mapped_column(JSONB, nullable=True)
